<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Korean Language Classes | Overseas Education Lane</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@500;700;800&family=Noto+Sans+KR:wght@700;900&family=DM+Sans:wght@400;500;700&display=swap">
<style>
:root{--bg:#fbf8f2;--ink:#0a1230;--mut:#50587a;--blue:#1387f2;--navy:#16109a;--red:#ee1c1c;--card:#fff;--line:#e4dfd3;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0b1024;--ink:#f4f6ff;--mut:#a3abd0;--card:#141b3a;--line:#252d57}}
*{box-sizing:border-box;margin:0}
html{scroll-behavior:smooth;scroll-padding-top:env(safe-area-inset-top,0px);overflow-x:hidden;max-width:100%;width:100%}
body{background:var(--bg);color:var(--ink);font:400 17px/1.6 'DM Sans',system-ui,sans-serif;overflow-x:hidden;max-width:100%;width:100%;position:relative}
h1,h2,h3{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;line-height:1.05;letter-spacing:-.02em}
.wrap{max-width:1080px;margin:0 auto;padding:0 22px}
img{max-width:100%}
#bar{position:fixed;top:0;left:0;height:4px;width:0;background:linear-gradient(90deg,var(--red),var(--blue),var(--navy));z-index:50}
nav{display:flex;justify-content:space-between;align-items:center;padding:16px 0}
nav img{height:46px;background:#fff;border-radius:10px;padding:4px 8px}
.btn{display:inline-block;border:0;cursor:pointer;font:700 17px 'DM Sans',sans-serif;color:#fff;background:var(--red);padding:15px 28px;border-radius:999px;text-decoration:none;position:relative;overflow:hidden;transition:transform .2s,box-shadow .2s;box-shadow:0 8px 24px -8px var(--red)}
.btn:hover{transform:translateY(-3px) scale(1.03)}
.btn:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--blue);outline-offset:3px}
.btn::after{content:"";position:absolute;top:0;left:-80%;width:50%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.55),transparent);transform:skewX(-20deg);animation:shine 3s infinite}
@keyframes shine{0%,60%{left:-80%}100%{left:140%}}
.pulse{animation:pulse 2s infinite}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(238,28,28,.55)}70%{box-shadow:0 0 0 18px rgba(238,28,28,0)}100%{box-shadow:0 0 0 0 rgba(238,28,28,0)}}
/* hero */
.hero{position:relative;overflow:hidden;background:linear-gradient(120deg,#0a0f6b,#1b17c9,#1387f2,#16109a);background-size:300% 300%;animation:bg 14s ease infinite;color:#fff;padding-bottom:44px}
@keyframes bg{50%{background-position:100% 50%}}
.hero nav{position:relative;z-index:2}
.hero .wrap{position:relative;z-index:2}
.hero-in{padding:24px 0 16px;max-width:760px}
.tag{display:inline-block;background:#ffffff22;border:1px solid #ffffff55;padding:5px 14px;border-radius:99px;font-size:14px;margin-bottom:14px;backdrop-filter:blur(6px)}
h1{font-size:clamp(30px,5vw,56px);font-weight:800;line-height:1.08}
h1 .w{display:inline-block;overflow:hidden;vertical-align:bottom;margin-right:.22em;padding-bottom:.08em}
h1 .w span{display:inline-block;transform:translateY(110%) rotate(6deg);animation:up .9s cubic-bezier(.2,.9,.2,1) forwards}
@keyframes up{to{transform:none}}
.hero p.lead{font-size:16.5px;max-width:520px;margin:12px 0 20px;opacity:0;animation:fade 1s .9s forwards;line-height:1.45}
.hero .btn{opacity:0;animation:fade 1s 1.2s forwards,pulse 2s 2.4s infinite}
@keyframes fade{to{opacity:1}}
.han{position:absolute;font-family:'Noto Sans KR',sans-serif;font-weight:900;color:#fff;opacity:.12;user-select:none;animation:float 9s ease-in-out infinite;z-index:1}
@keyframes float{50%{transform:translateY(-34px) rotate(8deg)}}
.stats{display:flex;gap:28px;flex-wrap:wrap;margin-top:22px;opacity:0;animation:fade 1s 1.5s forwards}
.stats b{font:800 32px 'Bricolage Grotesque',sans-serif;display:block}
.stats small{opacity:.8}
/* marquee */
.mq{background:var(--ink);color:var(--bg);overflow:hidden;white-space:nowrap;padding:14px 0;transform:rotate(-1.2deg);margin:-30px -10px 0;position:relative;z-index:3}
.mq div{display:inline-block;animation:mq 22s linear infinite;font:800 22px 'Noto Sans KR','Bricolage Grotesque',sans-serif}
.mq span{margin:0 26px}
@keyframes mq{to{transform:translateX(-50%)}}
section{padding:90px 0}
h2{font-size:clamp(34px,5.5vw,56px);font-weight:800;margin-bottom:12px}
.sub{color:var(--mut);max-width:560px;margin-bottom:46px}
/* plans */
.plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px;perspective:1200px}
.plan{border-radius:28px;padding:32px 26px;color:#fff;position:relative;transform-style:preserve-3d;transition:transform .15s ease-out,box-shadow .3s;display:flex;flex-direction:column;box-shadow:0 20px 40px -22px #0006}
.p2{background:linear-gradient(160deg,#ff3a2d,#d30f0f)}
.p3{background:linear-gradient(160deg,#3a2cff,#16109a)}
.p5{background:linear-gradient(160deg,#fff,#d9dde8);color:#0a1230}
.plan .n{font:800 78px/0.9 'Bricolage Grotesque',sans-serif}
.plan h3{font-size:30px;margin:4px 0 8px}
.plan .for{font-weight:700;margin-bottom:14px;opacity:.9}
.plan ul{list-style:none;padding:0;margin-bottom:18px;flex:1}
.plan li{padding:6px 0 6px 28px;position:relative}
.plan li::before{content:"✓";position:absolute;left:0;font-weight:800}
.dur{border-top:1px solid #ffffff55;padding-top:14px;font-weight:700}
.p5 .dur{border-color:#0a123044}
.price{font:800 44px 'Bricolage Grotesque',sans-serif;margin:4px 0 16px}
.price small{font:500 16px 'DM Sans'}
.plan .btn{background:#fff;color:#0a1230;text-align:center;box-shadow:none}
.p5 .btn{background:#0a1230;color:#fff}
.was{margin-top:8px;font-weight:700;font-size:20px;display:flex;align-items:center;gap:10px}.was s{opacity:.75;text-decoration-thickness:2px}.was em{font-style:normal;font-size:13px;background:#ffd400;color:#0a1230;padding:3px 10px;border-radius:99px;font-weight:800}.disc{position:absolute;right:22px;top:70px;width:150px;height:150px;border-radius:50%;background:#ffd400;color:#0a1230;display:grid;place-content:center;text-align:center;font-weight:800;line-height:1.05;box-shadow:0 16px 40px -10px #0008;animation:spin 14s linear infinite,pulse 2s infinite;z-index:3}.disc b{font:800 44px 'Bricolage Grotesque',sans-serif;display:block}.disc span{font-size:15px}.disc div{animation:spin 14s linear infinite reverse}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:760px){.disc{position:relative;right:auto;top:auto;margin:12px auto 16px;width:86px;height:86px;box-shadow:0 10px 25px -8px #0008;z-index:3}.disc b{font-size:24px}.disc span{font-size:10px}}
.badge{position:absolute;top:-14px;right:20px;background:#ffd400;color:#0a1230;font-weight:800;padding:6px 14px;border-radius:99px;font-size:14px;animation:wob 2.4s ease-in-out infinite}
@keyframes wob{50%{transform:rotate(6deg) scale(1.08)}}
/* features */
.feat{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px}
.f{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:26px;transition:transform .3s,border-color .3s}
.f:hover{transform:translateY(-6px) rotate(-.6deg);border-color:var(--blue)}
.f i{font-style:normal;font:900 34px 'Noto Sans KR',sans-serif;color:var(--blue);display:block;margin-bottom:6px}
.f h3{font-size:22px;margin-bottom:6px}
.f p{color:var(--mut);font-size:16px}
/* form */
.formsec{background:linear-gradient(160deg,#0a0f6b,#1387f2);color:#fff;padding:48px 0}
.box{display:grid;grid-template-columns:1fr 1fr;gap:32px;align-items:center}
.formsec .sub{color:#ffffffcc}
form{background:var(--card);color:var(--ink);padding:22px 20px;border-radius:22px;display:grid;gap:10px;box-shadow:0 30px 60px -30px #000a}
label,.field-wrap{font-weight:700;font-size:13.5px;display:grid;gap:4px}
input{font:inherit;padding:10px 12px;border-radius:10px;border:2px solid var(--line);background:var(--bg);color:var(--ink);transition:border-color .2s;width:100%;max-width:100%;min-width:0;box-sizing:border-box}
input:focus{border-color:var(--blue);transform:scale(1.015)}
input.is-invalid{border-color:#ef4444 !important;background:#fffbfa}
.field-err{display:none;color:#ef4444;font-size:11.5px;font-weight:600;line-height:1.3;margin-top:1px}
.field-err.show{display:block}
.custom-select{position:relative;width:100%;z-index:90}
.select-btn{width:100%;padding:10px 12px;border-radius:10px;border:2px solid var(--line);background:var(--bg);color:var(--ink);font:inherit;font-size:13.5px;font-weight:600;display:flex;align-items:center;justify-content:space-between;gap:8px;cursor:pointer;box-sizing:border-box;text-align:left}
.select-btn:focus,.select-btn.open{outline:0;border-color:var(--blue)}
.select-btn svg{flex-shrink:0;color:var(--blue);transition:transform .2s ease}
.select-btn.open svg{transform:rotate(180deg)}
.select-btn span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
.select-menu{position:absolute;top:calc(100% + 4px);left:0;right:0;width:100%;background:#ffffff;border:1.5px solid var(--blue);border-radius:12px;box-shadow:0 12px 30px -5px rgba(10,15,107,0.25);list-style:none;padding:5px;margin:0;display:none;z-index:999;box-sizing:border-box}
.select-menu.open{display:block}
.select-menu li{padding:9px 12px;font-size:13px;font-weight:600;color:var(--ink);border-radius:8px;cursor:pointer;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:background .15s ease,color .15s ease}
.select-menu li:hover,.select-menu li.selected{background:#eef2ff;color:var(--blue)}
.ok{display:none;text-align:center;padding:30px 10px}
.ok b{font:800 30px 'Bricolage Grotesque'}
form.done>*:not(.ok){display:none}form.done .ok{display:block}
footer{padding:20px 0 24px;text-align:center;color:#ffffff;opacity:.92;font-size:14px;position:relative;z-index:10}
.sticky{position:fixed;left:14px;right:14px;bottom:calc(14px + env(safe-area-inset-bottom,0px));z-index:40;text-align:center;transform:translateY(150%);transition:transform .4s;display:none}
.sticky.on{transform:none}
@media(max-width:760px){.sticky{display:block}}
.rev{padding-bottom:100px}.stage{position:relative;max-width:820px;height:340px;margin:0 auto;overflow:hidden}.rc{position:absolute;inset:0;display:grid;grid-template-columns:190px 1fr;gap:28px;align-items:center;background:linear-gradient(150deg,#16109a,#1387f2);color:#fff;border-radius:30px;padding:30px 34px;opacity:0;transform:translateX(70px) scale(.94);pointer-events:none;transition:opacity .6s,transform .7s cubic-bezier(.2,.8,.2,1);cursor:pointer;box-shadow:0 30px 60px -30px #16109a}.rc.on{opacity:1;transform:none;pointer-events:auto}.rc.out{transform:translateX(-70px) scale(.94)}.ring{position:relative;width:170px;height:170px;margin:auto}.ring svg{transform:rotate(-90deg)}.ring circle{fill:none;stroke-width:12}.ring .bg{stroke:#ffffff30}.ring .v{stroke:#ffd400;stroke-linecap:round;stroke-dasharray:402;stroke-dashoffset:402;transition:stroke-dashoffset 1.4s .3s ease}.rc.on .ring .v{stroke-dashoffset:var(--o)}.ring div{position:absolute;inset:0;display:grid;place-content:center;text-align:center;line-height:1.1}.ring b{font:800 40px 'Bricolage Grotesque',sans-serif}.ring small{opacity:.85;font-size:13px}.lvl{display:inline-block;background:#ffd400;color:#0a1230;font-weight:800;padding:4px 14px;border-radius:99px;font-size:14px;margin-bottom:12px}.rc q{display:block;font:500 clamp(18px,2.6vw,24px)/1.4 'DM Sans',sans-serif;quotes:none;margin-bottom:16px}.rc .who{font-weight:700}.rc .who small{display:block;font-weight:400;opacity:.85}.stars{color:#ffd400;letter-spacing:3px;margin-bottom:8px}.smp{position:absolute;top:12px;right:18px;font-size:12px;background:#0a123055;padding:3px 10px;border-radius:99px}.ctl{display:flex;align-items:center;justify-content:center;gap:16px;margin-top:26px}.ctl button{width:48px;height:48px;border-radius:50%;border:2px solid var(--blue);background:transparent;color:var(--blue);font-size:22px;cursor:pointer;transition:.2s}.ctl button:hover{background:var(--blue);color:#fff;transform:scale(1.1)}.dots{display:flex;gap:8px}.dots i{width:10px;height:10px;border-radius:99px;background:var(--line);cursor:pointer;transition:.3s}.dots i.on{width:34px;background:var(--blue)}.pg{max-width:820px;height:4px;background:var(--line);margin:22px auto 0;border-radius:9px;overflow:hidden}.pg i{display:block;height:100%;width:0;background:var(--red)}.pg i.run{animation:pgr 8s linear forwards}@keyframes pgr{to{width:100%}}
.pt{position:absolute;top:-20px;background:#ffc2d6;border-radius:100% 0 100% 0;opacity:.85;animation:fall linear infinite;z-index:1}@keyframes fall{to{transform:translate(90px,820px) rotate(540deg)}}.han{transition:translate .4s ease-out}
.try{background:linear-gradient(160deg,#0a0f6b,#16109a);color:#fff}.try .sub{color:#ffffffcc}.trybox{display:grid;grid-template-columns:1fr 1fr;gap:26px;align-items:center}.chips{display:grid;grid-template-columns:1fr 1fr;gap:12px}.chips button{font:900 22px 'Noto Sans KR',sans-serif;padding:18px 8px;border-radius:18px;border:2px solid #ffffff44;background:#ffffff14;color:#fff;cursor:pointer;transition:transform .25s,background .25s}.chips button:hover{transform:translateY(-4px)}.chips button.on{background:#ffd400;color:#0a1230;border-color:#ffd400;transform:scale(1.05) rotate(-2deg)}.panel{background:#fff;color:#0a1230;border-radius:28px;padding:30px 20px;text-align:center;min-height:270px}.panel>*{animation:pop .5s cubic-bezier(.2,.9,.3,1.3) both}.kr{font:900 clamp(38px,7vw,58px)/1.2 'Noto Sans KR',sans-serif}.rm{font:700 22px 'Bricolage Grotesque',sans-serif;color:var(--blue);margin-top:6px}.mn{color:#50587a;margin:4px 0 18px}.panel .btn{padding:11px 22px;font-size:16px}@keyframes pop{0%{transform:scale(.6) rotate(-6deg);opacity:0}100%{transform:none;opacity:1}}.cf{position:fixed;width:10px;height:10px;border-radius:3px;pointer-events:none;z-index:60;animation:cfa .9s ease-out forwards}@keyframes cfa{to{transform:translate(var(--x),var(--y)) rotate(360deg);opacity:0}}
.rv{opacity:0;transform:translateY(40px) scale(.97);transition:opacity .8s,transform .8s cubic-bezier(.2,.8,.2,1)}
.rv.in{opacity:1;transform:none}
