@media(max-width:420px){
  .stats{grid-template-columns:1fr!important;gap:14px!important}
  .hero-in .btn{width:100%!important}
  .stage{height:530px!important}
}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.rv,h1 .w span,.hero p.lead,.hero .btn,.stats{opacity:1!important;transform:none!important}}
</style>
</head>
<body>
<div id="bar"></div>
<header class="hero">
  <span class="han" style="left:4%;top:30%;font-size:120px">한</span>
  <span class="han" style="right:8%;top:14%;font-size:160px;animation-delay:-3s">국</span>
  <span class="han" style="right:20%;bottom:6%;font-size:100px;animation-delay:-6s">어</span>
  <div class="wrap">
    <nav><img src="data:image/png;base64," alt="Overseas Education Lane logo"><a class="btn" href="#join" style="padding:11px 20px;font-size:15px">Enrol now</a></nav>
    <div class="disc" aria-label="Flat 20 percent discount"><div><span>FLAT</span><b>20%</b><span>OFF</span></div></div>
    <div class="hero-in">
      <span class="tag">Live Korean language classes</span>
      <h1 id="h1">Speak Korean. Start today.</h1>
      <p class="lead">Learn with expert trainers in interactive classes and earn a certificate of completion. Pick the weekly pace that fits you best.</p>
      <a class="btn" href="#plans">See the 3 plans</a>
      <div class="stats">
        <div><b data-n="3">0</b><small>flexible plans</small></div>
        <div><b data-n="5">0</b><small>classes a week, max</small></div>
        <div><b>₹4,000</b><small>starting per month (20% off)</small></div>
      </div>
    </div>
  </div>
</header>
<div class="mq" aria-hidden="true"><div id="mq"></div></div>
<section id="plans">
  <div class="wrap">
    <h2 class="rv">Choose the Korean class that fits you best</h2>
    <p class="sub rv">Same a trainers and certificate in every plan. The only difference is how fast you want to go.</p>
    <div class="plans">
      <article class="plan p2 rv" data-tilt>
        <div class="n">2</div><h3>Classes per week</h3>
        <p class="for">For building strong foundations</p>
        <ul><li>Expert Trainers</li><li>Interactive Classes</li><li>Certificate of Completion</li><li>TOPIK Test Preparation</li><li>Steady learning, strong foundation</li></ul>
        <div class="dur">Course duration: 6 months</div>
        <div class="was"><s>₹5,000</s><em>20% OFF</em></div><div class="price" style="margin-top:0">₹4,000 <small>/ month</small></div>
        <a class="btn" href="#join" data-plan="2 Classes / Week – 6 Months – ₹4,000/mo">Buy now</a>
      </article>
      <article class="plan p3 rv" data-tilt>
        <div class="n">3</div><h3>Classes per week</h3>
        <p class="for">Ideal for developing Korean skills</p>
        <ul><li>Expert Trainers</li><li>Interactive Classes</li><li>Certificate of Completion</li><li>TOPIK Test Preparation</li><li>Balanced learning, greater progress</li></ul>
        <div class="dur">Course duration: 5 months</div>
        <div class="was"><s>₹6,250</s><em>20% OFF</em></div><div class="price" style="margin-top:0">₹5,000 <small>/ month</small></div>
        <a class="btn" href="#join" data-plan="3 Classes / Week – 5 Months – ₹5,000/mo">Buy now</a>
      </article>
      <article class="plan p5 rv" data-tilt>
        <span class="badge">Fast track</span>
        <div class="n">5</div><h3>Classes per week</h3>
        <p class="for">For intensive &amp; quick learning</p>
        <ul><li>Expert Trainers</li><li>Interactive Classes</li><li>Certificate of Completion</li><li>TOPIK Test Preparation</li><li>Fast-track learning, quick results</li></ul>
        <div class="dur">Course duration: 3–4 months</div>
        <div class="was"><s>₹11,250</s><em>20% OFF</em></div><div class="price" style="margin-top:0">₹9,000 <small>/ month</small></div>
        <a class="btn" href="#join" data-plan="5 Classes / Week – 3-4 Months – ₹9,000/mo">Buy now</a>
      </article>
    </div>
  </div>
</section>
<section style="padding-top:0">
  <div class="wrap">
    <h2 class="rv">Everything you need to learn Korean</h2>
    <p class="sub rv">Every plan comes with the same support from first class to certificate.</p>
    <div class="feat">
      <div class="f rv"><i>가</i><h3>Expert Trainers</h3><p>Learn from trainers who guide you step by step.</p></div>
      <div class="f rv"><i>나</i><h3>Interactive Classes</h3><p>Live sessions where you speak, listen and practise together.</p></div>
      <div class="f rv"><i>다</i><h3>Certificate of Completion</h3><p>Finish your course and take home proof of your progress.</p></div>
      <div class="f rv"><i>라</i><h3>Steady, Structured Learning</h3><p>A clear plan that builds a strong base in Korean.</p></div>
      <div class="f rv"><i>마</i><h3>TOPIK Test Preparation</h3><p>Get ready for the TOPIK exam as part of every plan.</p></div>
      <div class="f rv"><i>바</i><h3>Speaking Practice</h3><p>Build confidence by speaking Korean in every class.</p></div>
    </div>
  </div>
</section>
<section class="try"><div class="wrap">
    <h2 class="rv">Tap a word, hear Korean</h2>
    <p class="sub rv">A small taste of what you will learn in class.</p>
    <div class="trybox rv"><div class="chips" id="chips"></div><div class="panel"><div class="kr" id="kr"></div><div class="rm" id="rm"></div><div class="mn" id="mn"></div><button class="btn" id="say" type="button">🔊 Hear it</button></div></div>
  </div></section>
<section class="rev">
  <div class="wrap">
    <h2 class="rv">Our students’ TOPIK results</h2>
    <div class="rv" style="margin-bottom:46px"></div>
    <div class="stage rv" id="stage"></div>
    <div class="pg"><i id="pg"></i></div>
    <div class="ctl"><button id="pv" aria-label="Previous review">‹</button><div class="dots" id="dots"></div><button id="nx" aria-label="Next review">›</button><button id="pp" aria-label="Pause reviews" style="font-size:14px">❚❚</button></div>
  </div>
</section>
<section class="formsec" id="join">
  <div class="wrap box">
    <div class="rv">
      <h2>Reserve your seat today</h2>
      <p class="sub">Fill in your details, pick a plan and our team will contact you on WhatsApp to complete your enrolment.</p>
    </div>
    <form id="f" class="rv" novalidate>
      <label>Full name<input id="lName" required placeholder="Enter your full name" autocomplete="name"><small class="field-err" id="lErrName"></small></label>
      <label>Email address<input id="lEmail" required type="email" placeholder="Enter your email address" autocomplete="email"><small class="field-err" id="lErrEmail"></small></label>
      <label>Phone number<input id="lPhone" required type="tel" placeholder="Enter your 10-digit WhatsApp number" autocomplete="tel" maxlength="10"><small class="field-err" id="lErrPhone"></small></label>
      <label>City<input id="lCity" required placeholder="Enter your city" autocomplete="address-level2"><small class="field-err" id="lErrCity"></small></label>
      <div class="field-wrap">
        <span>Class Plan</span>
        <input type="hidden" id="plan" name="plan" value="3 Classes / Week – 5 Months – ₹5,000/mo">
        <div class="custom-select" id="customPlanDropdown">
          <button type="button" class="select-btn" id="customPlanBtn">
            <span id="customPlanText">3 Classes/Wk &middot; 5 Mo (&#8377;5,000/mo)</span>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
          </button>
          <ul class="select-menu" id="customPlanMenu">
            <li data-val="2 Classes / Week – 6 Months – ₹4,000/mo">2 Classes/Wk &middot; 6 Mo (&#8377;4,000/mo)</li>
            <li data-val="3 Classes / Week – 5 Months – ₹5,000/mo" class="selected">3 Classes/Wk &middot; 5 Mo (&#8377;5,000/mo)</li>
            <li data-val="5 Classes / Week – 3-4 Months – ₹9,000/mo">5 Classes/Wk &middot; 3-4 Mo (&#8377;9,000/mo)</li>
          </ul>
        </div>
      </div>
      <button class="btn pulse" type="submit">Buy now</button>
      <div class="ok"><b>감사합니다! Thank you.</b><p>We have your details. We will message you on WhatsApp shortly.</p></div>
    </form>
  </div>
  <footer>© Overseas Education Lane. All rights reserved.</footer>
</section>
<a class="btn sticky" id="st" href="#plans">Pick your Korean plan</a>
<script>
// headline word reveal
var h=document.getElementById('h1'),t=h.textContent.split(' ');h.innerHTML=t.map(function(w,i){return '<span class="w"><span style="animation-delay:'+(.15+i*.14)+'s">'+w+'</span></span>'}).join('');
// marquee
var m=['안녕하세요','Learn Korean','감사합니다','Live classes','화이팅','Expert trainers','한국어','Certificate'];
var s=m.map(function(x){return '<span>'+x+'</span>'}).join('');document.getElementById('mq').innerHTML=s+s+s+s;
// scroll reveal + counters
var io=new IntersectionObserver(function(e){e.forEach(function(x){if(x.isIntersecting){x.target.classList.add('in');io.unobserve(x.target)}})},{threshold:.15});
document.querySelectorAll('.rv').forEach(function(el,i){el.style.transitionDelay=(i%4)*.08+'s';io.observe(el)});
document.querySelectorAll('[data-n]').forEach(function(el){var n=+el.dataset.n,c=0,iv=setInterval(function(){el.textContent=++c;if(c>=n)clearInterval(iv)},400)});
// progress bar + sticky CTA
var bar=document.getElementById('bar'),st=document.getElementById('st');
addEventListener('scroll',function(){var d=document.documentElement,p=scrollY/(d.scrollHeight-innerHeight);bar.style.width=p*100+'%';st.classList.toggle('on',scrollY>500&&document.getElementById('join').getBoundingClientRect().top>innerHeight*.6)},{passive:true});
// 3D tilt
document.querySelectorAll('[data-tilt]').forEach(function(c){
  c.addEventListener('mousemove',function(e){var r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;c.style.transform='rotateY('+x*10+'deg) rotateX('+-y*10+'deg) translateY(-8px)'});
  c.addEventListener('mouseleave',function(){c.style.transform=''});
});
// plan buttons preselect plan
var cpBtn=document.getElementById('customPlanBtn'),cpMenu=document.getElementById('customPlanMenu'),cpTxt=document.getElementById('customPlanText'),cpHidden=document.getElementById('plan');
function closePlan(){if(cpMenu)cpMenu.classList.remove('open');if(cpBtn)cpBtn.classList.remove('open')}
function setPlan(val,txt){if(cpHidden)cpHidden.value=val;if(cpTxt)cpTxt.textContent=txt;if(cpMenu)cpMenu.querySelectorAll('li').forEach(function(li){li.classList.toggle('selected',li.getAttribute('data-val')===val)});closePlan()}
if(cpBtn&&cpMenu){
  cpBtn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();if(cpMenu.classList.contains('open')){closePlan()}else{cpMenu.classList.add('open');cpBtn.classList.add('open')}});
  cpMenu.querySelectorAll('li').forEach(function(li){li.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();setPlan(li.getAttribute('data-val'),li.textContent)})});
  document.addEventListener('click',function(e){if(!e.target.closest('#customPlanDropdown')){closePlan()}});
}
document.querySelectorAll('[data-plan]').forEach(function(b){b.addEventListener('click',function(){var p=b.dataset.plan;if(cpMenu&&p){cpMenu.querySelectorAll('li').forEach(function(li){if(li.getAttribute('data-val')===p)setPlan(p,li.textContent)})}})});
// petals + parallax
var hd=document.querySelector('.hero');
for(var k=0;k<14;k++){var pt=document.createElement('span');pt.className='pt';var sz=8+Math.random()*10;pt.style.cssText='left:'+Math.random()*100+'%;width:'+sz+'px;height:'+sz*.7+'px;animation-duration:'+(9+Math.random()*9)+'s;animation-delay:-'+Math.random()*14+'s';hd.appendChild(pt)}
hd.addEventListener('mousemove',function(e){var x=e.clientX/innerWidth-.5,y=e.clientY/innerHeight-.5;hd.querySelectorAll('.han').forEach(function(h,i){var d=(i+1)*22;h.style.translate=(x*d)+'px '+(y*d)+'px'})});
// tap a word
var W=[['안녕하세요','Annyeonghaseyo','Hello'],['감사합니다','Gamsahamnida','Thank you'],['화이팅','Hwaiting','You can do it!'],['한국어','Hangugeo','Korean language'],['친구','Chingu','Friend'],['맛있어요','Masisseoyo','It is delicious']],wi=0,chs=document.getElementById('chips');
chs.innerHTML=W.map(function(w,i){return '<button type="button" data-i="'+i+'"'+(i?'':' class="on"')+'>'+w[0]+'</button>'}).join('');
function speak(){try{var u=new SpeechSynthesisUtterance(W[wi][0]);u.lang='ko-KR';speechSynthesis.cancel();speechSynthesis.speak(u)}catch(e){}}
function showW(i,ev){wi=i;var p=document.querySelector('.panel'),w=W[i];kr.textContent=w[0];rm.textContent=w[1];mn.textContent=w[2];[].forEach.call(p.children,function(c){c.style.animation='none';void c.offsetWidth;c.style.animation=''});[].forEach.call(chs.children,function(b,j){b.classList.toggle('on',j===i)});if(ev){var cl=['#ffd400','#ee1c1c','#1387f2','#fff'];for(var n=0;n<18;n++){var c=document.createElement('i');c.className='cf';var a=Math.random()*6.28,r=60+Math.random()*90;c.style.cssText='left:'+ev.clientX+'px;top:'+ev.clientY+'px;background:'+cl[n%4]+';--x:'+Math.cos(a)*r+'px;--y:'+Math.sin(a)*r+'px';document.body.appendChild(c);setTimeout(function(el){el.remove()},900,c)}speak()}}
var kr=document.getElementById('kr'),rm=document.getElementById('rm'),mn=document.getElementById('mn');showW(0);
chs.addEventListener('click',function(e){if(e.target.dataset.i)showW(+e.target.dataset.i,e)});
document.getElementById('say').onclick=speak;
// reviews (SAMPLE content: replace with real student results, then set SAMPLE=false)
var SAMPLE=false;
var R=[
{n:'Sagar Sinha',c:'',p:'3 classes/week · 5 months',l:'TOPIK I · Level 2',s:160,m:200,q:'The trainers explained everything slowly and the interactive classes made me confident to speak Korean.'},
{n:'Akansha Agnihotri',c:'',p:'2 classes/week · 6 months',l:'TOPIK II · Level 3',s:150,m:300,q:'I started from zero. The steady pace gave me a strong foundation and now I can read Hangul easily.'},
{n:'Devansh Maheshwari',c:'',p:'5 classes/week · 3 months',l:'TOPIK II · Level 4',s:168,m:300,q:'The fast-track plan was perfect for my exam date. Daily classes kept me on track.'},
{n:'Sushant Aggarwal',c:'',p:'3 classes/week · 5 months',l:'TOPIK II · Level 5',s:220,m:300,q:'TOPIK preparation was part of the course, so I knew exactly what to expect on exam day.'},
{n:'Shrishti Tawade',c:'',p:'5 classes/week · 4 months',l:'TOPIK I · Level 2',s:145,m:200,q:'Great trainers and a certificate at the end. I would recommend this class to my friends.'}];
var stg=document.getElementById('stage'),dts=document.getElementById('dots'),pgb=document.getElementById('pg'),cur=0,tm;
stg.innerHTML=R.map(function(r,i){return '<div class="rc'+(i?'':' on')+'" style="--o:'+(402*(1-r.s/r.m)).toFixed(0)+'">'+(SAMPLE?'<span class="smp">Sample review</span>':'')+'<div class="ring"><svg width="170" height="170" viewBox="0 0 150 150"><circle class="bg" cx="75" cy="75" r="64"/><circle class="v" cx="75" cy="75" r="64"/></svg><div><b>'+r.s+'</b><small>out of '+r.m+'</small></div></div><div><span class="lvl">'+r.l+'</span><div class="stars">★★★★★</div><q>'+r.q+'</q><div class="who">'+r.n+'<small>'+r.p+'</small></div></div></div>'}).join('');
dts.innerHTML=R.map(function(_,i){return '<i'+(i?'':' class="on"')+' data-i="'+i+'"></i>'}).join('');
var cs=stg.children,ds=dts.children;
function go(n){n=(n+R.length)%R.length;if(n===cur)return;var p=cs[cur];p.classList.remove('on');p.classList.add('out');setTimeout(function(){p.classList.remove('out')},750);cs[n].classList.add('on');ds[cur].classList.remove('on');ds[n].classList.add('on');cur=n;run()}
var paused=false,pb=document.getElementById('pp');
function run(){clearInterval(tm);pgb.classList.remove('run');void pgb.offsetWidth;pgb.classList.add('run');pgb.style.animationPlayState=paused?'paused':'running';if(!paused)tm=setInterval(function(){go(cur+1)},8000)}
pb.onclick=function(){paused=!paused;pb.textContent=paused?'▶':'❚❚';pb.setAttribute('aria-label',paused?'Play reviews':'Pause reviews');if(paused){clearInterval(tm);pgb.style.animationPlayState='paused'}else run()};
stg.addEventListener('mouseenter',function(){if(!paused){clearInterval(tm);pgb.style.animationPlayState='paused'}});
stg.addEventListener('mouseleave',function(){if(!paused)run()});
document.getElementById('nx').onclick=function(){go(cur+1)};document.getElementById('pv').onclick=function(){go(cur-1)};
stg.addEventListener('click',function(){go(cur+1)});
dts.addEventListener('click',function(e){if(e.target.dataset.i)go(+e.target.dataset.i)});
var tx=0;stg.addEventListener('touchstart',function(e){tx=e.touches[0].clientX},{passive:true});stg.addEventListener('touchend',function(e){var d=e.changedTouches[0].clientX-tx;if(Math.abs(d)>40)go(cur+(d<0?1:-1))});
run();
// form
var fForm=document.getElementById('f'),lInName=document.getElementById('lName'),lInEmail=document.getElementById('lEmail'),lInPhone=document.getElementById('lPhone'),lInCity=document.getElementById('lCity');
var lErrN=document.getElementById('lErrName'),lErrE=document.getElementById('lErrEmail'),lErrP=document.getElementById('lErrPhone'),lErrC=document.getElementById('lErrCity');
function setErr(inp,el,m){if(inp)inp.classList.add('is-invalid');if(el){el.textContent=m;el.classList.add('show')}}
function clrErr(inp,el){if(inp)inp.classList.remove('is-invalid');if(el){el.textContent='';el.classList.remove('show')}}
function chkN(){var v=lInName?lInName.value.trim():'';if(!v){setErr(lInName,lErrN,'Please enter your full name.');return false}if(!/^[a-zA-Z\s]{3,50}$/.test(v)){setErr(lInName,lErrN,'Name must contain letters only (min 3 characters).');return false}clrErr(lInName,lErrN);return true}
function chkE(){var v=lInEmail?lInEmail.value.trim():'';if(!v){setErr(lInEmail,lErrE,'Please enter your email address.');return false}if(!/^[^\s@]+@[^\s@]+\.[a-zA-Z]{2,}$/.test(v)){setErr(lInEmail,lErrE,'Please enter a valid email address.');return false}clrErr(lInEmail,lErrE);return true}
function chkP(){var v=lInPhone?lInPhone.value.trim():'';if(!v){setErr(lInPhone,lErrP,'Please enter your WhatsApp number.');return false}if(!/^[6-9]\d{9}$/.test(v)){setErr(lInPhone,lErrP,'Please enter a valid 10-digit mobile number.');return false}clrErr(lInPhone,lErrP);return true}
function chkC(){var v=lInCity?lInCity.value.trim():'';if(!v){setErr(lInCity,lErrC,'Please enter your city.');return false}if(!/^[a-zA-Z\s]{2,50}$/.test(v)){setErr(lInCity,lErrC,'City must contain letters only (min 2 characters).');return false}clrErr(lInCity,lErrC);return true}
if(lInPhone){lInPhone.addEventListener('input',function(){this.value=this.value.replace(/\D/g,'').slice(0,10);if(this.classList.contains('is-invalid'))chkP()});lInPhone.addEventListener('blur',function(){if(this.value.trim())chkP()})}
if(lInName){lInName.addEventListener('input',function(){if(this.classList.contains('is-invalid'))chkN()});lInName.addEventListener('blur',function(){if(this.value.trim())chkN()})}
if(lInEmail){lInEmail.addEventListener('input',function(){if(this.classList.contains('is-invalid'))chkE()});lInEmail.addEventListener('blur',function(){if(this.value.trim())chkE()})}
if(lInCity){lInCity.addEventListener('input',function(){if(this.classList.contains('is-invalid'))chkC()});lInCity.addEventListener('blur',function(){if(this.value.trim())chkC()})}
fForm.addEventListener('submit',function(e){e.preventDefault();var oN=chkN(),oE=chkE(),oP=chkP(),oC=chkC();if(!oN||!oE||!oP||!oC){if(!oN)lInName.focus();else if(!oE)lInEmail.focus();else if(!oP)lInPhone.focus();else if(!oC)lInCity.focus();return}this.classList.add('done')});
</script>
</body>
</html>